const data = $input.first().json;

// Einfachen Token generieren (32 hex chars)
function generateToken() {
  const chars = '0123456789abcdef';
  let token = '';
  for (let i = 0; i < 64; i++) token += chars[Math.floor(Math.random() * 16)];
  return token;
}

const token = generateToken();
const expiresAt = new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString();

return [{ json: {
  ...data,
  token: token,
  expires_at: expiresAt
}}];

const dbResult = $input.first().json;
const inputData = $node['🔐 Token generieren'].json;

// Resume URL vom Wait-Node (wird vom n8n Wait-Node automatisch bereitgestellt)
// Hier erstellen wir die Approval-URLs mit dem Token als Parameter
const baseUrl = $env.N8N_BASE_URL;
const token = inputData.token;

// Diese URL wird nach dem Wait-Node ausgefüllt
return [{ json: {
  ...inputData,
  token_db_id: dbResult.id,
  // Temporäre Platzhalter – werden im Wait-Node-Callback ersetzt
  token: token,
  base_url: baseUrl
}}];

// Nach Wait-Node: Resume URL ist jetzt bekannt ($execution.resumeUrl wurde genutzt)
const waitData = $input.first().json;
const origData = $node['🔐 Token generieren'].json;

// Die Entscheidung kam über die Webhook-URL mit ?decision=approve oder ?decision=reject
const decision = waitData.query?.decision || waitData.body?.decision || 'unknown';
const token = origData.token;
const actionType = origData.action_type;
const summary = origData.approval_summary || '';
const sessionData = origData.session_data || {};
const staffEmail = origData.staff_email || $env.STAFF_EMAIL_PRIMARY;
const fullData = origData.full_data || {};

return [{ json: {
  decision: decision,
  approved: decision === 'approve',
  token: token,
  action_type: actionType,
  approval_summary: summary,
  session_id: origData.session_id,
  session_data: sessionData,
  staff_email: staffEmail,
  full_data: fullData
}}];

const data = $input.first().json;
const actionType = data.action_type;
const sessionData = data.session_data || {};
const fullData = data.full_data || {};
const summary = data.approval_summary || '';
const userIdentifier = sessionData.user_identifier || '';
const channel = sessionData.channel || 'unbekannt';
const firmaName = $env.FIRMA_NAME || 'Ihre Zeitarbeitsfirma';
const staffEmail = data.staff_email;
const token = data.token;

// E-Mail Betreff
let subject, userMessage, userEmail;

if (actionType === 'new_applicant') {
  subject = `✅ GENEHMIGT: Neuer Bewerber – ${fullData.full_name || userIdentifier}`;
  userMessage = `Sehr geehrte/r ${fullData.full_name || 'Bewerber/in'},\n\nvielen Dank für Ihr Interesse an ${firmaName}!\n\nIhre Daten wurden erfolgreich aufgenommen und von unserem Team geprüft. Wir werden uns in Kürze mit Ihnen in Verbindung setzen, um einen Termin für ein persönliches Gespräch zu vereinbaren.\n\nBei Fragen stehen wir Ihnen gerne zur Verfügung.\n\nMit freundlichen Grüßen,\nIhr Team bei ${firmaName}`;
  userEmail = fullData.email || '';
} else if (actionType === 'new_company') {
  subject = `✅ GENEHMIGT: Neue Unternehmensanfrage – ${fullData.company_name || userIdentifier}`;
  userMessage = `Sehr geehrte/r ${fullData.contact_person || 'Ansprechpartner/in'},\n\nvielen Dank für Ihre Anfrage bei ${firmaName}!\n\nIhre Personalanfrage wurde aufgenommen und von unserem Team geprüft. Ein/e Ansprechpartner/in wird sich zeitnah bei Ihnen melden.\n\nMit freundlichen Grüßen,\nIhr Kundenberatungs-Team bei ${firmaName}`;
  userEmail = fullData.email || '';
} else if (actionType === 'appointment') {
  subject = `✅ GENEHMIGT: Terminbestätigung`;
  userMessage = `Sehr geehrte/r Nutzer/in,\n\nIhr Termin wurde bestätigt! Sie erhalten in Kürze eine separate Terminbestätigung per E-Mail.\n\nMit freundlichen Grüßen,\nIhr Team bei ${firmaName}`;
  userEmail = fullData.email || '';
} else {
  subject = `✅ Anfrage genehmigt`;
  userMessage = `Ihre Anfrage wurde bearbeitet. Ein Mitarbeiter wird sich in Kürze bei Ihnen melden.`;
  userEmail = fullData.email || '';
}

// Mitarbeiter-Benachrichtigung
const staffNotificationHtml = `
<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><style>
body{font-family:Arial,sans-serif;max-width:600px;margin:0 auto;background:#f0f9f0;}
.box{background:white;border-radius:8px;padding:25px;margin:20px;border-left:5px solid #27ae60;}
h2{color:#27ae60;} .data{background:#f8f8f8;padding:12px;border-radius:4px;white-space:pre-wrap;font-family:monospace;font-size:13px;}
.badge{background:#27ae60;color:white;padding:3px 10px;border-radius:12px;font-size:12px;}
</style></head><body><div class="box">
<h2>✅ Genehmigung erteilt</h2>
<p>Token: <span class="badge">${token}</span></p>
<p><strong>Aktion:</strong> ${actionType}</p>
<div class="data">${summary}</div>
<p style="color:#666;font-size:12px;margin-top:20px;">Nutzer wurde automatisch benachrichtigt. Kanal: ${channel}</p>
</div></body></html>`;

return [{ json: {
  ...data,
  email_to_user: userEmail,
  email_subject_user: 'Ihre Anfrage bei ' + firmaName,
  email_body_user: userMessage,
  email_to_staff: staffEmail,
  email_subject_staff: subject,
  email_html_staff: staffNotificationHtml,
  has_user_email: !!userEmail
}}];

const data = $input.first().json;
const sessionData = data.session_data || {};
const fullData = data.full_data || {};
const firmaName = $env.FIRMA_NAME || 'Ihre Zeitarbeitsfirma';
const staffEmail = data.staff_email;
const token = data.token;
const summary = data.approval_summary || '';
const userIdentifier = sessionData.user_identifier || '';

const staffHtml = `
<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><style>
body{font-family:Arial,sans-serif;max-width:600px;margin:0 auto;background:#fff5f5;}
.box{background:white;border-radius:8px;padding:25px;margin:20px;border-left:5px solid #e74c3c;}
h2{color:#e74c3c;} .data{background:#f8f8f8;padding:12px;border-radius:4px;white-space:pre-wrap;font-family:monospace;font-size:13px;}
</style></head><body><div class="box">
<h2>❌ Anfrage abgelehnt</h2>
<p><strong>Token:</strong> ${token}</p>
<div class="data">${summary}</div>
<p><strong>Nutzer:</strong> ${userIdentifier} (${sessionData.channel || ''})</p>
<p style="color:#666;font-size:12px;">Bitte setzen Sie sich ggf. manuell mit dem Nutzer in Verbindung.</p>
</div></body></html>`;

return [{ json: {
  ...data,
  email_to_staff: staffEmail,
  email_subject_staff: `❌ Abgelehnt: ${data.action_type} – ${fullData.full_name || fullData.company_name || userIdentifier}`,
  email_html_staff: staffHtml
}}];

const data = $node['🔗 URLs vorbereiten'].json;
const token = data.token;
const actionType = data.action_type;
const summary = data.approval_summary || 'Keine Zusammenfassung';
const sessionData = data.session_data || {};
const fullData = data.full_data || {};
const staffEmail = data.staff_email || $env.STAFF_EMAIL_PRIMARY;
const firmaName = $env.FIRMA_NAME || 'Zeitarbeitsfirma';

// Resume URL vom n8n Wait-Node
const resumeUrl = $execution.resumeUrl;
const approveUrl = `${resumeUrl}?decision=approve&token=${token}`;
const rejectUrl = `${resumeUrl}?decision=reject&token=${token}`;
const expiry = new Date(Date.now() + 72 * 60 * 60 * 1000).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const actionLabel = {
  'new_applicant': '👤 Neuer Bewerber',
  'new_company': '🏢 Neue Unternehmensanfrage',
  'appointment': '📅 Terminanfrage',
  'escalation': '⚠️ Eskalation'
}[actionType] || actionType;

// Nutzer-Infos für E-Mail Header
const userName = fullData.full_name || fullData.company_name || fullData.contact_person || sessionData.user_identifier || 'Unbekannt';
const userEmail = fullData.email || '';
const userPhone = fullData.phone || '';

const html = `<!DOCTYPE html>
<html lang="de">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Genehmigung erforderlich</title>
<style>
  body { font-family: -apple-system, Arial, sans-serif; margin: 0; padding: 0; background: #f0f2f5; }
  .wrapper { max-width: 620px; margin: 20px auto; }
  .header { background: #2c3e50; color: white; padding: 24px 30px; border-radius: 10px 10px 0 0; }
  .header h1 { margin: 0; font-size: 20px; }
  .header p { margin: 6px 0 0; opacity: 0.8; font-size: 14px; }
  .body { background: white; padding: 30px; }
  .badge { display: inline-block; padding: 5px 14px; border-radius: 20px; font-size: 13px; font-weight: 600; background: #3498db; color: white; margin-bottom: 16px; }
  .summary { background: #f8f9fa; border-left: 4px solid #3498db; border-radius: 4px; padding: 16px 18px; margin: 20px 0; white-space: pre-wrap; font-family: 'Courier New', monospace; font-size: 13px; line-height: 1.6; color: #333; }
  .meta { display: flex; gap: 20px; margin: 16px 0; flex-wrap: wrap; }
  .meta-item { background: #f8f9fa; padding: 8px 14px; border-radius: 6px; font-size: 13px; }
  .meta-label { color: #666; font-size: 11px; display: block; }
  .actions { text-align: center; padding: 24px 0; border-top: 1px solid #eee; border-bottom: 1px solid #eee; margin: 24px 0; }
  .btn { display: inline-block; padding: 14px 36px; border-radius: 8px; text-decoration: none; font-weight: 700; font-size: 16px; margin: 8px; }
  .btn-approve { background: #27ae60; color: white; }
  .btn-reject { background: #e74c3c; color: white; }
  .warning { background: #fff3cd; border: 1px solid #ffc107; border-radius: 6px; padding: 12px 16px; font-size: 13px; margin: 16px 0; }
  .footer { background: #f8f9fa; padding: 16px 30px; border-radius: 0 0 10px 10px; font-size: 12px; color: #888; }
</style>
</head>
<body>
<div class="wrapper">
  <div class="header">
    <h1>🤖 Maria – Genehmigung erforderlich</h1>
    <p>${firmaName} · Virtueller Rezeptionist</p>
  </div>
  <div class="body">
    <span class="badge">${actionLabel}</span>

    <div class="meta">
      <div class="meta-item"><span class="meta-label">Kontakt</span>${userName}</div>
      ${userEmail ? `<div class="meta-item"><span class="meta-label">E-Mail</span>${userEmail}</div>` : ''}
      ${userPhone ? `<div class="meta-item"><span class="meta-label">Telefon</span>${userPhone}</div>` : ''}
      <div class="meta-item"><span class="meta-label">Kanal</span>${sessionData.channel || 'unbekannt'}</div>
    </div>

    <p><strong>Zusammenfassung der gesammelten Daten:</strong></p>
    <div class="summary">${summary.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</div>

    <div class="warning">⏰ Läuft ab: <strong>${expiry} Uhr</strong> (72 Stunden)</div>

    <div class="actions">
      <p style="color:#555;margin-bottom:16px;">Bitte prüfen Sie die Daten und entscheiden Sie:</p>
      <a href="${approveUrl}" class="btn btn-approve">✅ GENEHMIGEN</a>
      <a href="${rejectUrl}" class="btn btn-reject">❌ ABLEHNEN</a>
    </div>

    <p style="font-size:13px;color:#666;">Nach Ihrer Entscheidung wird der Nutzer automatisch benachrichtigt und die Daten entsprechend verarbeitet.</p>
  </div>
  <div class="footer">
    Automatisch generiert von Maria · ${firmaName} · Token: ${token}
  </div>
</div>
</body>
</html>`;

return [{ json: {
  email_to: staffEmail,
  email_subject: `🔔 Genehmigung erforderlich: ${actionLabel} – ${userName}`,
  email_html: html,
  // Weitergabe für späteren Verarbeitungsschritt
  original_data: data,
  token: token,
  resume_url: resumeUrl
}}];
